namespace CheckoutPricing.Domain;

public sealed class LoyaltyDiscountPolicy
{
    public int DiscountCentsFor(int subtotalCents, LoyaltyTier loyaltyTier) =>
        subtotalCents * RatePercent(loyaltyTier) / 100;

    private static int RatePercent(LoyaltyTier loyaltyTier) => loyaltyTier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 10,
        LoyaltyTier.Gold => 15,
        _ => throw new ArgumentOutOfRangeException(nameof(loyaltyTier))
    };
}
EOF
cat > src/CheckoutPricing.Application/CalculateLoyaltyDiscount.cs <<'EOF'
using CheckoutPricing.Domain;

namespace CheckoutPricing.Application;

public sealed record CalculateLoyaltyDiscountQuery(int SubtotalCents, LoyaltyTier LoyaltyTier);

public sealed record LoyaltyDiscountQuote(
    int SubtotalCents,
    int DiscountCents,
    int TotalCents,
    LoyaltyTier LoyaltyTier);

public sealed class CalculateLoyaltyDiscount
{
    private readonly LoyaltyDiscountPolicy policy = new();

    public LoyaltyDiscountQuote Handle(CalculateLoyaltyDiscountQuery query)
    {
        var discountCents = policy.DiscountCentsFor(query.SubtotalCents, query.LoyaltyTier);
        return new(query.SubtotalCents, discountCents, query.SubtotalCents - discountCents, query.LoyaltyTier);
    }
}
EOF
