namespace CheckoutPricing.Domain;

public sealed class LoyaltyDiscountPolicy
{
    private const int MinimumSubtotalCents = 3_000;
    private const int CapCents = 2_000;

    public int DiscountCentsFor(int subtotalCents, LoyaltyTier loyaltyTier)
    {
        if (subtotalCents < MinimumSubtotalCents)
        {
            return 0;
        }

        return Math.Min(subtotalCents * RatePercent(loyaltyTier) / 100, CapCents);
    }

    private static int RatePercent(LoyaltyTier loyaltyTier) => loyaltyTier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 10,
        LoyaltyTier.Gold => 15,
        LoyaltyTier.Platinum => 20,
        _ => throw new ArgumentOutOfRangeException(nameof(loyaltyTier))
    };
}

namespace CheckoutPricing.Domain;

public sealed class PromoCodePolicy
{
    private const int Welcome5Cents = 500;
    private const int Summer10CapCents = 1_500;

    public int DiscountCentsFor(string? promoCode, int amountAfterLoyaltyCents)
    {
        if (string.Equals(promoCode, "WELCOME5", StringComparison.OrdinalIgnoreCase))
        {
            return Welcome5Cents;
        }

        if (string.Equals(promoCode, "SUMMER10", StringComparison.OrdinalIgnoreCase))
        {
            return Math.Min(amountAfterLoyaltyCents / 10, Summer10CapCents);
        }

        return 0;
    }
}

namespace CheckoutPricing.Domain;

public sealed class ShippingFeePolicy
{
    private const int StandardFeeCents = 490;
    private const int ExpressFeeCents = 990;
    private const int FreeStandardFromCents = 5_000;

    public int FeeCentsFor(int payableTotalCents, LoyaltyTier loyaltyTier, bool express) =>
        express ? ExpressFee(loyaltyTier) : StandardFee(payableTotalCents, loyaltyTier);

    private static int ExpressFee(LoyaltyTier loyaltyTier) =>
        loyaltyTier == LoyaltyTier.Platinum ? 0 : ExpressFeeCents;

    private static int StandardFee(int payableTotalCents, LoyaltyTier loyaltyTier)
    {
        var freeForTier = loyaltyTier is LoyaltyTier.Gold or LoyaltyTier.Platinum;
        return freeForTier || payableTotalCents >= FreeStandardFromCents ? 0 : StandardFeeCents;
    }
}

using CheckoutPricing.Domain;

