using CheckoutPricing.Domain;

namespace CheckoutPricing.Application;

public sealed record CalculateLoyaltyDiscountQuery(int SubtotalCents, LoyaltyTier LoyaltyTier, string? PromoCode = null);

public sealed record LoyaltyDiscountQuote(
    int SubtotalCents,
    int DiscountCents,
    int TotalCents,
    LoyaltyTier LoyaltyTier);

public sealed class CalculateLoyaltyDiscount
{
    private readonly LoyaltyDiscountPolicy loyaltyPolicy = new();
    private readonly LoyaltyDiscountLimits limits = new();
    private readonly PromoCodePolicy promoPolicy = new();

    public LoyaltyDiscountQuote Handle(CalculateLoyaltyDiscountQuery query)
    {
        var loyaltyCents = limits.Apply(
            query.SubtotalCents,
            loyaltyPolicy.DiscountCentsFor(query.SubtotalCents, query.LoyaltyTier));
        var promoCents = promoPolicy.DiscountCentsFor(query.PromoCode, query.SubtotalCents - loyaltyCents);
        var discountCents = Math.Min(loyaltyCents + promoCents, query.SubtotalCents);
        return new(query.SubtotalCents, discountCents, query.SubtotalCents - discountCents, query.LoyaltyTier);
    }
}

